import { useColorScheme as useNativewindColorScheme } from 'nativewind';

import { palette, type ThemeColors } from './colors';

/** Effective (resolved) color scheme + helpers. */
export function useColorScheme() {
  const { colorScheme, setColorScheme, toggleColorScheme } = useNativewindColorScheme();
  const resolved = colorScheme ?? 'light';
  return {
    colorScheme: resolved,
    isDark: resolved === 'dark',
    setColorScheme,
    toggleColorScheme,
  };
}

/** Resolved palette for the current scheme (for native props / icons). */
export function useThemeColors(): ThemeColors {
  const { isDark } = useColorScheme();
  return isDark ? palette.dark : palette.light;
}

import { DarkTheme, DefaultTheme } from 'expo-router';

import { palette } from './colors';

/** React Navigation themes used by Expo Router's `ThemeProvider`. */
export const navLightTheme = {
  ...DefaultTheme,
  colors: {
    ...DefaultTheme.colors,
    primary: palette.light.primary,
    background: palette.light.background,
    card: palette.light.card,
    text: palette.light.foreground,
    border: palette.light.border,
    notification: palette.light.primary,
  },
};

export const navDarkTheme = {
  ...DarkTheme,
  colors: {
    ...DarkTheme.colors,
    primary: palette.dark.primary,
    background: palette.dark.background,
    card: palette.dark.card,
    text: palette.dark.foreground,
    border: palette.dark.border,
    notification: palette.dark.primary,
  },
};

import {
  Inter_400Regular,
  Inter_500Medium,
  Inter_600SemiBold,
  Inter_700Bold,
  Inter_800ExtraBold,
  useFonts,
} from '@expo-google-fonts/inter';

/**
 * Custom fonts loaded at runtime. Inter is wired up as the example family; swap
 * in your own by installing another `@expo-google-fonts/*` package (or dropping
 * `.ttf` files into `assets/fonts/` and `require()`-ing them here), then point
 * `fontFamily.sans` at the regular face in `tailwind.config.js` and rewrite the
 * face names in `plugins/interFontPlugin.js`.
 *
 * Use them through the ordinary Tailwind weight utilities — `font-medium`,
 * `font-semibold`, `font-bold` — never a bespoke `font-<family>` class. The
 * plugin turns those weights into these face names on native.
 *
 * Every face here has to be referenced by the plugin and vice versa: a face
 * loaded but never mapped is dead bundle weight, and a face mapped but never
 * loaded falls back to the system font without any error.
 */
export const fontMap = {
  Inter_400Regular,
  Inter_500Medium,
  Inter_600SemiBold,
  Inter_700Bold,
  Inter_800ExtraBold,
};

/**
 * Loads the app fonts. Returns `true` once they're ready (or failed — we don't
 * block the splash screen forever on a font error). Call it where the splash is
 * gated (see `app/_layout.tsx`).
 */
export function useAppFonts(): boolean {
  const [loaded, error] = useFonts(fontMap);
  return loaded || error != null;
}

// Trimmed for the registry: theme-provider is coupled to templapp's
// app layer, and ships with the template rather than with this item.
export { useColorScheme, useThemeColors } from './use-color-scheme';
export { useAppFonts, fontMap } from './fonts';
export { palette, type ThemeColors } from './colors';
export { navLightTheme, navDarkTheme } from './navigation';
